import json, numpy as np
from sklearn.linear_model import Ridge
rows=json.load(open('observations.json'))
# Reset-aware test: y is a three-step convolution of an instantaneous control contribution q(x,z,c), plus the observed reset offset.
eps=[]; cur=[]
for r in rows:
    if not r['history'] and cur: eps.append(cur); cur=[]
    cur.append(r)
if cur: eps.append(cur)
print('rows',len(rows),'episodes',len(eps))
def features(u,thr):
    x,z,c=u
    h=float(c<thr)
    return np.array([x,z,x*x,z*z,x*z,c,x*c,z*c,x*x*c,z*z*c,x*z*c,h*x,h*z,h*x*z,h*x*x,h*z*z,h*x*c,h*z*c])
def make(ep,thr):
    X=[]; y=[]; groups=[]
    for gi,e in enumerate(ep):
        us=[(r['features']['x'],r['features']['z'],r['features']['c']) for r in e]
        fs=[features(u,thr) for u in us]
        for t,r in enumerate(e):
            v=sum((fs[j] for j in range(max(0,t-2),t+1)),np.zeros(fs[0].size))
            # reset-only baseline transient is known; learn remaining intercept through q
            b=[-0.27472345791918956,-0.5494469158383791,-0.8241703737575687][min(t,2)]
            X.append(v); y.append(r['target']-b); groups.append(gi)
    return np.asarray(X),np.asarray(y),np.asarray(groups)
for thr in [-.25,-.22,-.20,-.18,-.1775,-.17625,-.175,-.17,-.15,0]:
    X,y,g=make(eps,thr); pred=np.zeros_like(y)
    for k in range(len(eps)):
        tr=g!=k; te=~tr
        m=Ridge(alpha=1e-9).fit(X[tr],y[tr]); pred[te]=m.predict(X[te])
    print('threshold',thr,'LOEO_MSE',round(float(np.mean((pred-y)**2)),6),'pooled',round(float(np.mean((Ridge(alpha=1e-9).fit(X,y).predict(X)-y)**2)),8))
